import { workspace } from "@/config/site";
import { analyseLocally } from "./engine";
import { seedKit } from "@/features/brand-kit/data";
import type { AuditEntry, Review } from "../types";

const ago = (minutes: number) => new Date(Date.now() - minutes * 60000).toISOString();
const audit = (id: string, at: string, actor: string, kind: AuditEntry["kind"], message: string): AuditEntry => ({ id, at, actor, kind, message });

/** Example workspace, generated by the real engine so seeded reviews behave exactly like new ones. */
export function buildSeed(): Review[] {
  const base = { brandKit: workspace.brandKit, mode: "Full brand review", source: "local-demo" as const };

  const c1 = "Introducing the all-new Zippy Bottle.\n\nIndia's #1 fastest delivery, guaranteed.\n\nGrab one today, or miss out!!!\n\nImage: banner.png";
  const a1 = analyseLocally({ title: "", channel: "", content: c1, brandKit: "", mode: "" }, seedKit);

  const c2 = "Hi there,\n\nMeet the Zippy Bottle — made with BPA-free, food-grade stainless steel.\n\nIt ships this week.";
  const c3 = "October product update\n\nThe Zippy Bottle has a 750 ml capacity. Fast delivery is available in select cities.";

  return [
    {
      ...base, id: "GL-2048", title: "Summer launch announcement", channel: "Social media", creator: "Aarav Mehta",
      createdAt: ago(190), updatedAt: ago(46), status: "Needs attention", content: c1, originalContent: c1,
      summary: a1.summary, findings: a1.findings,
      audit: [audit("AU-1", ago(190), "Aarav Mehta", "submitted", "Submitted for review"), audit("AU-2", ago(189), "Greenlight", "analysis", a1.summary)]
    },
    {
      ...base, id: "GL-2047", title: "Product feature email", channel: "Email", creator: "Maya Shah",
      createdAt: ago(330), updatedAt: ago(120), status: "In review", content: c2,
      originalContent: c2.replace("Meet the Zippy Bottle", "Meet the zippy bottle"),
      summary: "1 potential issue detected by local rule checks. Human review is required.",
      findings: [{
        id: "FD-04", category: "Terminology", severity: "Medium", quote: "zippy bottle", resolvedText: "Zippy Bottle", ruleId: "T-08", confidence: 97, status: "Edited", suggestionKind: "replace",
        reason: "“zippy bottle” does not match the approved language. Approved product name and capitalisation.",
        receipt: "Terminology list · T-08 — avoid “Zippy bottle”, use “Zippy Bottle”", suggestion: "Zippy Bottle"
      }],
      audit: [
        audit("AU-3", ago(330), "Maya Shah", "submitted", "Submitted for review"),
        audit("AU-4", ago(329), "Greenlight", "analysis", "1 potential issue detected by local rule checks. Human review is required."),
        audit("AU-5", ago(120), "Maya Shah", "finding", "Edited wording for “zippy bottle”")
      ]
    },
    {
      ...base, id: "GL-2041", title: "October product update", channel: "Website", creator: "Rohan Das",
      createdAt: ago(1800), updatedAt: ago(1500), status: "Approved", content: c3, originalContent: c3,
      summary: "0 potential issues detected by local rule checks. Human review is required.", findings: [],
      audit: [
        audit("AU-6", ago(1800), "Rohan Das", "submitted", "Submitted for review"),
        audit("AU-7", ago(1799), "Greenlight", "analysis", "0 potential issues detected by local rule checks. Human review is required."),
        audit("AU-8", ago(1500), "Maya Shah", "status", "Approved content for publication")
      ]
    }
  ];
}
